176	 ****************************************************************************/
177	static void audio_frontend_process(struct xiaozhi_audio_s *a,
178	                                   opus_int16 *buf, int samples)
179	{
180	  int i;
181	  int voice_detected = 0;
182	
183	  /* ---- 1. DC 去除 (单极点高通滤波) ----
184	   * y[n] = y[n-1] + alpha * (x[n] - y[n-1])
185	   * alpha = 328/32768 ≈ 0.01, fc ≈ 100Hz @ 16kHz
186	   * 去除麦克风直流偏移，改善后续处理效果 */
187	  for (i = 0; i < samples; i++)
188	    {
189	      int32_t s = buf[i];
190	      a->dc_avg += ((s << 15) - a->dc_avg) >> 15;
191	      s = s - (a->dc_avg >> 15);
192	      if (s > 32767) s = 32767;
193	      if (s < -32768) s = -32768;
194	      buf[i] = (opus_int16)s;
195	    }
196	
197	  /* ---- 2. AGC 自动增益控制 ----
198	   * 测量每帧峰值，动态调整增益使峰值接近目标值。
199	   * 麦克风原始峰值~960，目标~16000，需约16倍增益。
200	   * 攻击快(右移8位)、衰减慢(右移4位)，避免增益泵浦。 */
201	  {
202	    int16_t frame_peak = 0;
203	    for (i = 0; i < samples; i++)
204	      {
205	        int16_t abs_s = buf[i];
206	        if (abs_s < 0) abs_s = -abs_s;
207	        if (abs_s > frame_peak) frame_peak = abs_s;
208	      }
209	
210	    if (a->agc_gain == 0 && frame_peak > 0)
211	      {
212	        /* 首帧初始化增益 */
213	        a->agc_gain = ((int32_t)AF_AGC_TARGET << 10) / frame_peak;
214	      }
215	    else if (frame_peak > 0)
216	      {
217	        int32_t desired = ((int32_t)AF_AGC_TARGET << 10) / frame_peak;
218	        if (desired < a->agc_gain)
219	          {
220	            /* 攻击: 快速降低增益 */
221	            a->agc_gain -= (a->agc_gain - desired) >> AF_AGC_ATTACK;
222	          }
223	        else
224	          {
225	            /* 衰减: 慢速提升增益 */
226	            a->agc_gain += (desired - a->agc_gain) >> AF_AGC_DECAY;
227	          }
228	      }
229	
230	    /* 增益范围限制: 1x ~ 32x */
231	    if (a->agc_gain < 1024)  a->agc_gain = 1024;
232	    if (a->agc_gain > 32768) a->agc_gain = 32768;
233	
