static void *uplink_worker(void *arg)
{
  struct uplink_ctx_s *uc = arg;
  struct xiaozhi_app_s *app = uc->app;
  uint8_t frame[XZ_OPUS_MAX];
  uint8_t outbuf[sizeof(struct xz_binary_hdr_s) + XZ_OPUS_MAX];
  int frames = 0;
  int target_frames = (uc->seconds * 1000) / 60;   /* 60ms per frame */

  printf("[xiaozhi] uplink: capturing %d frames (%ds)\n",
         target_frames, uc->seconds);


  printf("[xiaozhi] app->ws_connected %d\n", app->ws_connected);

  while (frames < target_frames && app->ws_connected)
    {
      printf("[xiaozhi] in while show, frames=%d, target=%d, connected=%d\n",
             frames, target_frames, app->ws_connected);
      ssize_t n = xiaozhi_audio_read_opus(app->audio, frame, sizeof(frame));
      printf("[xiaozhi] read_opus returned: %zd\n", n);
      if (n < 0)
        {
          printf("[xiaozhi] uplink read err: %zd\n", n);
          break;
        }

      if (n > 0)
        {
          /* Debug: hex dump first Opus frames for format verification. */
          if (frames < 3)
            {
              printf("[xiaozhi] opus frame[%d] len=%zd\n", frames, n);
              for (ssize_t i = 0; i < n && i < 32; i++)
                {
                  printf("%02x ", frame[i]);
                }
              printf("\n");
            }

          /* Prepend binary protocol header (v3) for server parsing. */
          struct xz_binary_hdr_s *hdr = (struct xz_binary_hdr_s *)outbuf;
          hdr->type = 0;                          /* OPUS */
          hdr->reserved = 0;
          hdr->payload_size = htons((uint16_t)n); /* big-endian */
          memcpy(outbuf + sizeof(*hdr), frame, n);

          int ret = xiaozhi_ws_send_binary(&app->ws, outbuf,
                                           sizeof(*hdr) + n);
          if (ret != 0)
            {
              printf("[xiaozhi] uplink send err: %d\n", ret);
              break;
            }

          frames++;
        }
    }

  printf("[xiaozhi] uplink: sent %d/%d frames\n", frames, target_frames);
  return NULL;
}

