594	/* Sanitize UTF-8 text: replace fullwidth CJK punctuation with ASCII
595	 * equivalents so the limited CJK font (basic ideographs only) can render
596	 * all visible characters without falling back to [][].
597	 */
598	static void sanitize_text(char *dst, size_t dstsize, const char *src)
599	{
600	  size_t di = 0;
601	  const unsigned char *s = (const unsigned char *)src;
602	
603	  while (*s && di < dstsize - 1)
604	    {
605	      /* 3-byte UTF-8: U+0800 .. U+FFFF */
606	      if (s[0] >= 0xe0 && s[1] >= 0x80 && s[1] < 0xc0 &&
607	          s[2] >= 0x80 && s[2] < 0xc0)
608	        {
609	          unsigned int cp = ((unsigned int)(s[0] & 0x0f) << 12) |
610	                            ((unsigned int)(s[1] & 0x3f) << 6) |
611	                            ((unsigned int)(s[2] & 0x3f));
612	          const char *r = NULL;
613	
614	          switch (cp)
615	            {
616	              case 0xff0c: r = ",";  break;  /* ， */
617	              case 0x3002: r = ".";  break;  /* 。 */
618	              case 0xff01: r = "!";  break;  /* ！ */
619	              case 0xff1f: r = "?";  break;  /* ？ */
620	              case 0xff1a: r = ":";  break;  /* ： */
621	              case 0xff1b: r = ";";  break;  /* ； */
622	              case 0x3001: r = ",";  break;  /* 、 */
623	              case 0x201c: r = "\""; break;  /* " */
624	              case 0x201d: r = "\""; break;  /* " */
625	              case 0x2018: r = "'";  break;  /* ' */
626	              case 0x2019: r = "'";  break;  /* ' */
627	              case 0xff08: r = "(";  break;  /* （ */
628	              case 0xff09: r = ")";  break;  /* ） */
629	              case 0x300a: r = "<<"; break;  /* 《 */
630	              case 0x300b: r = ">>"; break;  /* 》 */
631	              case 0x2026: r = "..."; break; /* … */
632	              case 0x2014: r = "--"; break;  /* — */
633	              default:
634	                {
635	                  /* Keep the original character if it's in CJK range */
636	                  if (cp >= 0x4e00 && cp <= 0x9fa5)
637	                    {
638	                      dst[di++] = s[0];
639	                      dst[di++] = s[1];
640	                      dst[di++] = s[2];
641	                    }
642	                  else
643	                    {
644	                      /* Unknown char: skip */
645	                    }
646	                  s += 3;
647	                  continue;
648	                }
649	            }
650	
651	          /* Write replacement string */
652	          while (*r && di < dstsize - 1)
653	            {
654	              dst[di++] = *r++;
655	            }
656	
657	          s += 3;
658	        }
659	      /* 2-byte UTF-8: U+0080 .. U+07FF (skip, not CJK) */
660	      else if (s[0] >= 0xc0 && s[0] < 0xe0 && s[1] >= 0x80)
661	        {
662	          s += 2;
663	        }
664	      /* ASCII */
665	      else if (s[0] < 0x80)
666	        {
667	          dst[di++] = *s++;
668	        }
669	      else
670	        {
671	          /* Invalid UTF-8 byte, skip */
672	          s++;
673	        }
674	    }
675	
676	  dst[di] = '\0';
677	}
