694	/* Uplink worker: capture Opus frames and send as binary frames for the
695	 * given number of seconds.
696	 */
697	static void *uplink_worker(void *arg)
698	{
699	  struct uplink_ctx_s *uc = arg;
700	  struct xiaozhi_app_s *app = uc->app;
701	  uint8_t frame[XZ_OPUS_MAX];
702	  int frames = 0;
703	  int target_frames = (uc->seconds * 1000) / 60;   /* 60ms per frame */
704	
705	  printf("[xiaozhi] uplink: capturing %d frames (%ds)\n",
706	         target_frames, uc->seconds);
707	
708	  
709	  printf("[xiaozhi] app->ws_connected %d\n", app->ws_connected);
710	
711	  while (frames < target_frames && app->ws_connected)
712	    {
713	      printf("[xiaozhi] in while show, frames=%d, target=%d, connected=%d\n",
714	             frames, target_frames, app->ws_connected);
715	      ssize_t n = xiaozhi_audio_read_opus(app->audio, frame, sizeof(frame));
716	      printf("[xiaozhi] read_opus returned: %zd\n", n);
717	      if (n < 0)
718	        {
719	          printf("[xiaozhi] uplink read err: %zd\n", n);
720	          break;
721	        }
722	
723	      if (n > 0)
724	        {
725	          /* Debug: hex dump first Opus frames for format verification. */
726	          if (frames < 3)
727	            {
728	              printf("[xiaozhi] opus frame[%d] len=%zd\n", frames, n);
729	              for (ssize_t i = 0; i < n && i < 32; i++)
730	                {
731	                  printf("%02x ", frame[i]);
732	                }
733	              printf("\n");
734	            }
735	
736	          /* 加上 BinaryProtocol3 头再发送，否则服务器无法正确切分 opus 负载。 */
737	          struct xz_binary_hdr_s *hdr;
738	          uint8_t outbuf[sizeof(*hdr) + XZ_OPUS_MAX];
739	
740	          hdr = (struct xz_binary_hdr_s *)outbuf;
741	          hdr->type = 0;                 /* 0 = OPUS */
742	          hdr->reserved = 0;
743	          hdr->payload_size = htons((uint16_t)n);
744	          memcpy(outbuf + sizeof(*hdr), frame, n);
745	
746	          int ret = xiaozhi_ws_send_binary(&app->ws, outbuf, sizeof(*hdr) + n);
747	          if (ret != 0)
748	            {
749	              printf("[xiaozhi] uplink send err: %d\n", ret);
750	              break;
751	            }
752	
753	          frames++;
754	        }
755	    }
756	
757	  printf("[xiaozhi] uplink: sent %d/%d frames\n", frames, target_frames);
758	  return NULL;
759	}
