761	/* Receive worker: parse server messages and feed TTS audio to the player.
762	 * Runs until ws is closed or a stop condition.
763	 */
764	static void recv_loop(struct xiaozhi_app_s *app, int max_ms,
765	                      bool stop_on_hello)
766	{
767	  int waited = 0;
768	
769	  while (app->ws_connected && waited < max_ms && !app->mcp_done)
770	    {
771	      const uint8_t *payload;
772	      size_t plen;
773	      bool is_binary;
774	      int ret;
775	
776	      ret = xiaozhi_ws_recv(&app->ws, &payload, &plen, &is_binary);
777	      if (ret != 0)
778	        {
779	          app->ws_connected = false;
780	          break;
781	        }
782	
783	      if (is_binary)
784	        {
785	          printf("[xiaozhi] <<< binary frame: %zu bytes\n", plen);
786	          /* Server TTS Opus frame -> feed to player. */
787	          if (app->tts_playing)
788	            {
789	              xiaozhi_audio_write_opus(app->audio, payload, plen);
790	            }
791	
792	          waited += 60;
793	          continue;
794	        }
795	
796	      /* Text frame: parse JSON. */
797	      {
798	        char *json = malloc(plen + 1);
799	        if (json == NULL)
800	          {
801	            continue;
802	          }
803	
804	        memcpy(json, payload, plen);
805	        json[plen] = '\0';
806	
807	        cJSON *root = cJSON_Parse(json);
808	        if (root != NULL)
809	          {
810	            /* Print all received text messages for debugging. */
811	            printf("[xiaozhi] <<< recv: %s\n", json);
812	
813	            cJSON *type = cJSON_GetObjectItem(root, "type");
814	            const char *tstr = cJSON_IsString(type) ?
815	              type->valuestring : "";
816	
817	            if (strcmp(tstr, "stt") == 0)
818	              {
819	                cJSON *text = cJSON_GetObjectItem(root, "text");
820	                const char *s = text ? text->valuestring : "?";
821	                printf("[xiaozhi] <<< STT: \"%s\"\n", s);
822	                app->got_stt = true;
823	                sanitize_text(app->stt_text, sizeof(app->stt_text), s);
824	              }
825	            else if (strcmp(tstr, "llm") == 0)
826	              {
827	                cJSON *text = cJSON_GetObjectItem(root, "text");
828	                printf("[xiaozhi] <<< LLM: \"%s\"\n",
829	                       text ? text->valuestring : "?");
830	              }
831	            else if (strcmp(tstr, "tts") == 0)
832	              {
833	                cJSON *state = cJSON_GetObjectItem(root, "state");
834	                const char *sstr = cJSON_IsString(state) ?
835	                  state->valuestring : "";
836	
837	                if (strcmp(sstr, "start") == 0)
838	                  {
839	                    pthread_mutex_lock(&s_ui_mutex);
840	                    app->tts_playing = true;
841	                    app->state = XZ_STATE_PLAYING;
842	                    pthread_mutex_unlock(&s_ui_mutex);
843	                    xiaozhi_audio_start_playback(app->audio);
844	                    printf("[xiaozhi] <<< TTS start\n");
845	                  }
846	                else if (strcmp(sstr, "stop") == 0)
847	                  {
848	                    app->tts_playing = false;
849	                    printf("[xiaozhi] <<< TTS stop\n");
850	                    xiaozhi_audio_stop_playback(app->audio);
851	                    cJSON_Delete(root);
852	                    free(json);
853	                    break;   /* end of this turn */
854	                  }
855	                else if (strcmp(sstr, "sentence_start") == 0)
856	                  {
857	                    cJSON *text = cJSON_GetObjectItem(root, "text");
858	                    const char *s = text ? text->valuestring : "?";
859	                    printf("[xiaozhi] <<< TTS: \"%s\"\n", s);
860	                    app->tts_sentences++;
861	                    sanitize_text(app->tts_text, sizeof(app->tts_text), s);
862	                  }
863	              }
864	            else if (strcmp(tstr, "goodbye") == 0)
865	              {
866	                printf("[xiaozhi] <<< goodbye\n");
867	                app->ws_connected = false;
868	                cJSON_Delete(root);
869	                free(json);
870	                break;
871	              }
872	            else if (strcmp(tstr, "mcp") == 0)
873	              {
874	                printf("[xiaozhi] <<< MCP message\n");
875	                /* Check if this is tools/list — after responding, the MCP
876	                 * handshake is complete and we should proceed to listen.
877	                 */
878	                cJSON *payload = cJSON_GetObjectItem(root, "payload");
879	                cJSON *method = payload ?
880	                  cJSON_GetObjectItem(payload, "method") : NULL;
881	                bool is_tools_list = cJSON_IsString(method) &&
882	                  strcmp(method->valuestring, "tools/list") == 0;
883	
884	                mcp_server_handle_message(root, mcp_send_json);
885	
886	                if (is_tools_list)
887	                  {
888	                    printf("[xiaozhi] MCP handshake done\n");
889	                    app->mcp_done = true;
890	                  }
891	              }
892	            else if (strcmp(tstr, "hello") == 0)
893	              {
894	                cJSON *sid = cJSON_GetObjectItem(root, "session_id");
895	                if (cJSON_IsString(sid))
896	                  {
897	                    strncpy(app->session_id, sid->valuestring,
898	                            sizeof(app->session_id) - 1);
899	                    app->session_id[sizeof(app->session_id) - 1] = '\0';
900	                    printf("[xiaozhi] <<< hello: session_id=%s\n",
901	                           app->session_id);
902	                  }
903	
904	                /* In the connect phase we only need the hello response to
905	                 * obtain the session_id; bail out so we don't block here
906	                 * waiting for server audio that never comes before we've
907	                 * sent listen:start. The server also times out (~10s) if
908	                 * it doesn't see a listen request soon after hello.
909	                 */
910	                if (stop_on_hello)
911	                  {
912	                    cJSON_Delete(root);
913	                    free(json);
914	                    return;
915	                  }
916	              }
917	            else
918	              {
919	                /* Print full message for debugging unknown types (e.g. error). */
920	                char *out = cJSON_PrintUnformatted(root);
921	                printf("[xiaozhi] <<< %s\n", out ? out : tstr);
922	                if (out)
923	                  {
924	                    free(out);
925	                  }
926	              }
927	
928	            cJSON_Delete(root);
929	          }
930	        else
931	          {
932	            printf("[xiaozhi] <<< (parse err) %.*s\n",
933	                   (int)plen, (const char *)payload);
934	          }
935	
936	        free(json);
937	      }
938	
939	      waited += 60;
940	    }
941	}
