943	/* Dialog thread: runs the full OTA -> dialog flow off the main (UI) thread.
944	 */
945	static void *dialog_thread(void *arg)
946	{
947	  struct xiaozhi_app_s *app = arg;
948	  struct xiaozhi_ota_config_s ota;
949	  const char *mac = XIAOZHI_MAC_DEFAULT;
950	  char client_id[40];
951	  int ret;
952	
953	  snprintf(client_id, sizeof(client_id),
954	           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);
955	
956	  /* Init audio subsystem (creates Opus encoder). */
957	  app->audio = xiaozhi_audio_init();
958	  if (app->audio == NULL)
959	    {
960	      printf("[xiaozhi] audio init failed\n");
961	      app->state = XZ_STATE_ERROR;
962	      return NULL;
963	    }
964	
965	  /* Init MCP tool server and set app context for send callback. */
966	
967	  s_mcp_app = app;
968	  mcp_register_tools();
969	
970	  /* Step 1: OTA. */
971	  app->state = XZ_STATE_OTA;
972	  printf("[xiaozhi] step 1: OTA\n");
973	  ret = xiaozhi_ota_fetch(mac, &ota);
974	  if (ret != 0)
975	    {
976	      printf("[xiaozhi] OTA failed: %d\n", ret);
977	      app->state = XZ_STATE_ERROR;
978	      return NULL;
979	    }
980	
981	  /* Step 2: wss connect (TLS + ws upgrade). */
982	  app->state = XZ_STATE_CONNECT;
983	  printf("[xiaozhi] step 2: wss connect\n");
984	  ret = xiaozhi_ws_connect(&app->ws, ota.ws_url, ota.ws_token, mac,
985	                           client_id);
986	  if (ret != 0)
987	    {
988	      printf("[xiaozhi] ws connect failed: %d\n", ret);
989	      app->state = XZ_STATE_ERROR;
990	      return NULL;
991	    }
992	
993	  app->ws_connected = true;
994	
995	  /* Step 3: send the hello handshake, then wait for the server's hello
996	   * response which carries the session_id. The server times out (~10s)
997	   * if it never receives a hello, so we must send ours first.
998	   */
999	  printf("[xiaozhi] step 3: send hello + wait hello response\n");
1000	  {
1001	    cJSON *hello = cJSON_CreateObject();
1002	    cJSON_AddStringToObject(hello, "type", "hello");
1003	    cJSON_AddNumberToObject(hello, "version", 3);
1004	    cJSON_AddStringToObject(hello, "transport", "websocket");
1005	
1006	    cJSON *ap = cJSON_CreateObject();
1007	    cJSON_AddStringToObject(ap, "format", "opus");
1008	    cJSON_AddNumberToObject(ap, "sample_rate", 16000);
1009	    cJSON_AddNumberToObject(ap, "channels", 1);
1010	    cJSON_AddNumberToObject(ap, "frame_duration", 60);
1011	    cJSON_AddItemToObject(hello, "audio_params", ap);
1012	
1013	    /* Advertise MCP tool support to the server. */
1014	
1015	    mcp_server_add_hello_features(hello);
1016	
1017	    char *hello_str = cJSON_PrintUnformatted(hello);
1018	    printf("[xiaozhi] >>> hello json: %s\n", hello_str ? hello_str : "null");
1019	    if (hello_str)
1020	      {
1021	        free(hello_str);
1022	      }
1023	    ret = send_json(app, hello);
1024	    cJSON_Delete(hello);
1025	    if (ret != 0)
1026	      {
1027	        printf("[xiaozhi] hello send failed: %d\n", ret);
1028	        pthread_mutex_lock(&s_ui_mutex);
1029	        app->state = XZ_STATE_ERROR;
1030	        pthread_mutex_unlock(&s_ui_mutex);
1031	        goto out;
1032	      }
1033	  }
1034	
1035	  /* Receive the server hello response to get session_id. stop_on_hello
1036	   * returns immediately once we have it, so we don't block waiting for
1037	   * audio the server won't send before listen:start.
1038	   */
1039	  recv_loop(app, 5000, true);
1040	  if (app->session_id[0] == '\0')
1041	    {
1042	      printf("[xiaozhi] no session_id, abort\n");
1043	      pthread_mutex_lock(&s_ui_mutex);
1044	      app->state = XZ_STATE_ERROR;
1045	      pthread_mutex_unlock(&s_ui_mutex);
1046	      goto out;
1047	    }
1048	
1049	  /* Step 3b: Process MCP initialize from server.
1050	   * The server may send MCP initialize after hello but before we start
1051	   * listening. We need to handle it so the server knows our tools.
1052	   * The loop breaks early once tools/list is handled (mcp_done flag).
1053	   */
1054	
1055	  printf("[xiaozhi] step 3b: wait for MCP initialize\n");
1056	  app->mcp_done = false;
1057	  recv_loop(app, 3000, false);
1058	
1059	  /* Check if connection survived the MCP exchange.
1060	   * The TLS read may fail during recv_loop (error -0x5), killing
1061	   * the connection. If so, abort instead of continuing with a dead
1062	   * connection which would cause the dialog to loop forever.
1063	   */
1064	  if (!app->ws_connected)
1065	    {
1066	      printf("[xiaozhi] connection lost during MCP exchange, abort\n");
1067	      goto out;
1068	    }
1069	
1070	  /* Step 4: listen start + capture + listen stop. */
1071	  pthread_mutex_lock(&s_ui_mutex);
1072	  app->state = XZ_STATE_LISTENING;
1073	  pthread_mutex_unlock(&s_ui_mutex);
1074	  printf("[xiaozhi] step 4: listen start + capture, session_id=%s\n",
1075	         app->session_id);
1076	  {
1077	    cJSON *listen = cJSON_CreateObject();
1078	    cJSON_AddStringToObject(listen, "session_id", app->session_id);
1079	    cJSON_AddStringToObject(listen, "type", "listen");
1080	    cJSON_AddStringToObject(listen, "state", "start");
1081	    cJSON_AddStringToObject(listen, "mode", "manual");
1082	    char *json_str = cJSON_PrintUnformatted(listen);
1083	    printf("[xiaozhi] >>> listen start json: %s\n", json_str ? json_str : "null");
1084	    if (json_str)
1085	      {
1086	        free(json_str);
1087	      }
1088	    send_json(app, listen);
1089	    cJSON_Delete(listen);
1090	  }
1091	
1092	  ret = xiaozhi_audio_start_capture(app->audio);
1093	  if (ret != 0)
1094	    {
1095	      printf("[xiaozhi] capture start failed: %d\n", ret);
1096	      pthread_mutex_lock(&s_ui_mutex);
1097	      app->state = XZ_STATE_ERROR;
1098	      pthread_mutex_unlock(&s_ui_mutex);
1099	      goto out;
1100	    }
1101	
1102	  {
1103	    struct uplink_ctx_s uc;
1104	    uc.app = app;
1105	    uc.seconds = XZ_DIALOG_SECONDS;
1106	    uplink_worker(&uc);
1107	  }
1108	
1109	  xiaozhi_audio_stop_capture(app->audio);
1110	
1111	  /* listen stop. */
1112	  {
1113	    cJSON *stop = cJSON_CreateObject();
1114	    cJSON_AddStringToObject(stop, "session_id", app->session_id);
1115	    cJSON_AddStringToObject(stop, "type", "listen");
1116	    cJSON_AddStringToObject(stop, "state", "stop");
1117	    char *json_str = cJSON_PrintUnformatted(stop);
1118	    printf("[xiaozhi] >>> listen stop json: %s\n", json_str ? json_str : "null");
1119	    if (json_str)
1120	      {
1121	        free(json_str);
1122	      }
1123	    send_json(app, stop);
1124	    cJSON_Delete(stop);
1125	  }
1126	
1127	  /* Step 5: receive stt + tts + playback (up to 20s). */
1128	  app->state = XZ_STATE_THINKING;
1129	  printf("[xiaozhi] step 5: wait stt/tts (20s)\n");
1130	  app->mcp_done = false;  /* Reset so recv_loop doesn't exit early. */
1131	  recv_loop(app, 20000, false);
1132	
1133	out:
1134	  if (app->tts_playing)
1135	    {
1136	      xiaozhi_audio_stop_playback(app->audio);
1137	    }
1138	
1139	  xiaozhi_audio_deinit(app->audio);
1140	  xiaozhi_ws_close(&app->ws);
1141	
1142	  pthread_mutex_lock(&s_ui_mutex);
1143	  app->state = XZ_STATE_DONE;
1144	  pthread_mutex_unlock(&s_ui_mutex);
1145	  printf("[xiaozhi] === done: stt=%s tts=%d ===\n",
1146	         app->got_stt ? "yes" : "no", app->tts_sentences);
1147	
1148	  /* Reset state so user can start a new conversation. */
1149	  app->dialog_started = false;
1150	  app->ws_connected = false;
1151	  app->mcp_done = false;
1152	  app->got_stt = false;
1153	  app->tts_playing = false;
1154	  app->tts_sentences = 0;
1155	  memset(app->session_id, 0, sizeof(app->session_id));
1156	  memset(app->stt_text, 0, sizeof(app->stt_text));
1157	  memset(app->tts_text, 0, sizeof(app->tts_text));
1158	
1159	  /* Set flag to show start button - LVGL timer will handle the actual LVGL operation.
1160	   * Do NOT call lv_obj_clear_flag directly from this thread! */
1161	  app->show_start_btn = true;
1162	
1163	  return NULL;
1164	}
