1166	/* Start button click handler: kicks off the dialog thread on demand.
1167	 * The user taps this after WiFi is up, so OTA can reach the server.
1168	 */
1169	static void start_btn_event_cb(lv_event_t *e)
1170	{
1171	  struct xiaozhi_app_s *app = &g_app;
1172	  LV_UNUSED(e);
1173	
1174	  if (app->dialog_started)
1175	    {
1176	      return;   /* already running */
1177	    }
1178	
1179	  pthread_mutex_lock(&s_ui_mutex);
1180	  app->dialog_started = true;
1181	  app->state = XZ_STATE_OTA;
1182	  pthread_mutex_unlock(&s_ui_mutex);
1183	
1184	  /* Hide the start button once the dialog is launched. */
1185	  if (app->start_btn != NULL)
1186	    {
1187	      lv_obj_add_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
1188	    }
1189	
1190	  pthread_attr_t attr;
1191	  pthread_attr_init(&attr);
1192	  pthread_attr_setstacksize(&attr, 65536);
1193	
1194	  int ret = pthread_create(NULL, &attr, dialog_thread, app);
1195	  pthread_attr_destroy(&attr);
1196	
1197	  if (ret != 0)
1198	    {
1199	      printf("[xiaozhi] dialog thread create failed: %d\n", ret);
1200	      pthread_mutex_lock(&s_ui_mutex);
1201	      app->state = XZ_STATE_ERROR;
1202	      app->dialog_started = false;
1203	      pthread_mutex_unlock(&s_ui_mutex);
1204	      if (app->start_btn != NULL)
1205	        {
1206	          lv_obj_clear_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
1207	        }
1208	    }
1209	}
