1312	/* Refresh the LVGL screen from the shared app state.
1313	 * NOTE: This function performs LVGL operations and should only be called
1314	 * from LVGL timer callbacks (which run in the LVGL thread context).
1315	 * Do NOT call this from dialog_thread or any other thread directly.
1316	 */
1317	static void ui_refresh(struct xiaozhi_app_s *app)
1318	{
1319	  if (app->status_label != NULL)
1320	    {
1321	      lv_label_set_text(app->status_label, g_state_names[app->state]);
1322	    }
1323	
1324	  /* Only start/stop animations on state transitions, not every refresh. */
1325	  static int last_state = -1;
1326	  if (last_state != app->state)
1327	    {
1328	      /* 先停止所有动画 */
1329	      wave_anim_stop();
1330	      think_anim_stop();
1331	
1332	      if (app->state == XZ_STATE_LISTENING)
1333	        {
1334	          /* Listening状态：显示波形动画 */
1335	          if (xiaozhi_container != NULL)
1336	            {
1337	              wave_anim_start(xiaozhi_container);
1338	            }
1339	          /* You/Xiaozhi往下移动，避免被动画遮挡（动画底部约y=165） */
1340	          if (s_stt_caption != NULL)
1341	            {
1342	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 190);
1343	            }
1344	          if (app->stt_label != NULL)
1345	            {
1346	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 220);
1347	            }
1348	          if (s_tts_caption != NULL)
1349	            {
1350	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 280);
1351	            }
1352	          if (app->tts_label != NULL)
1353	            {
1354	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 310);
1355	            }
1356	        }
1357	      else if (app->state == XZ_STATE_THINKING)
1358	        {
1359	          /* Thinking状态：显示3个点动画 */
1360	          if (xiaozhi_container != NULL)
1361	            {
1362	              think_anim_start(xiaozhi_container);
1363	            }
1364	          /* You/Xiaozhi往下移动，避免被动画遮挡（动画底部约y=110） */
1365	          if (s_stt_caption != NULL)
1366	            {
1367	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 150);
1368	            }
1369	          if (app->stt_label != NULL)
1370	            {
1371	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 180);
1372	            }
1373	          if (s_tts_caption != NULL)
1374	            {
1375	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 240);
1376	            }
1377	          if (app->tts_label != NULL)
1378	            {
1379	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 270);
1380	            }
1381	        }
1382	      else if (app->state == XZ_STATE_PLAYING)
1383	        {
1384	          /* Playing状态：只隐藏label背景 */
1385	          if (s_stt_caption != NULL)
1386	            {
1387	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 180);
1388	              lv_obj_set_style_bg_opa(s_stt_caption, LV_OPA_TRANSP, 0);
1389	            }
1390	          if (app->stt_label != NULL)
1391	            {
1392	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 210);
1393	              lv_obj_set_style_bg_opa(app->stt_label, LV_OPA_TRANSP, 0);
1394	            }
1395	          if (s_tts_caption != NULL)
1396	            {
1397	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 270);
1398	              lv_obj_set_style_bg_opa(s_tts_caption, LV_OPA_TRANSP, 0);
1399	            }
1400	          if (app->tts_label != NULL)
1401	            {
1402	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 300);
1403	              lv_obj_set_style_bg_opa(app->tts_label, LV_OPA_TRANSP, 0);
1404	            }
1405	        }
1406	      else
1407	        {
1408	          /* 其他状态：恢复默认位置 */
1409	          if (s_stt_caption != NULL)
1410	            {
1411	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 180);
1412	            }
1413	          if (app->stt_label != NULL)
1414	            {
1415	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 210);
1416	            }
1417	          if (s_tts_caption != NULL)
1418	            {
1419	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 270);
1420	            }
1421	          if (app->tts_label != NULL)
1422	            {
1423	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 300);
1424	            }
1425	        }
1426	
1427	      last_state = app->state;
1428	    }
1429	
1430	  if (app->stt_label != NULL)
1431	    {
1432	      bool has_stt = app->stt_text[0] != '\0';
1433	      lv_label_set_text(app->stt_label, has_stt ? app->stt_text : "-");
1434	
1435	      /* Playing状态隐藏背景，其他状态根据内容显示/隐藏 */
1436	      lv_opa_t bg_opa;
1437	      if (app->state == XZ_STATE_PLAYING)
1438	        {
1439	          bg_opa = LV_OPA_TRANSP;
1440	        }
1441	      else
1442	        {
1443	          bg_opa = has_stt ? LV_OPA_COVER : LV_OPA_TRANSP;
1444	        }
1445	      lv_obj_set_style_bg_opa(app->stt_label, bg_opa, 0);
1446	      if (s_stt_caption != NULL)
1447	        {
1448	          lv_obj_set_style_bg_opa(s_stt_caption, bg_opa, 0);
1449	        }
1450	    }
1451	
1452	  if (app->tts_label != NULL)
1453	    {
1454	      bool has_tts = app->tts_text[0] != '\0';
1455	      lv_label_set_text(app->tts_label, has_tts ? app->tts_text : "-");
1456	
1457	      /* Playing状态隐藏背景，其他状态根据内容显示/隐藏 */
1458	      lv_opa_t bg_opa;
1459	      if (app->state == XZ_STATE_PLAYING)
1460	        {
1461	          bg_opa = LV_OPA_TRANSP;
1462	        }
1463	      else
1464	        {
1465	          bg_opa = has_tts ? LV_OPA_COVER : LV_OPA_TRANSP;
1466	        }
1467	      lv_obj_set_style_bg_opa(app->tts_label, bg_opa, 0);
1468	      if (s_tts_caption != NULL)
1469	        {
1470	          lv_obj_set_style_bg_opa(s_tts_caption, bg_opa, 0);
1471	        }
1472	    }
1473	
1474	  /* Handle show_start_btn flag from dialog_thread. */
1475	  if (app->show_start_btn && app->start_btn != NULL)
1476	    {
1477	      lv_obj_clear_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
1478	      app->show_start_btn = false;
1479	    }
1480	}
