1482	/* Timer callback to refresh UI periodically.
1483	 * NOTE: This runs in the LVGL timer thread context.
1484	 * Do NOT hold s_ui_mutex here - ui_refresh performs LVGL operations
1485	 * that should not be blocked by dialog_thread's network I/O.
1486	 */
1487	static void ui_refresh_timer_cb(lv_timer_t *timer)
1488	{
