1506	      lv_obj_clear_flag(xiaozhi_container, LV_OBJ_FLAG_HIDDEN);
1507	      return;
1508	    }
1509	
1510	  /* 初始化应用状态 */
1511	  memset(&g_app, 0, sizeof(g_app));
1512	  g_app.state = XZ_STATE_BOOT;
1513	
1514	  /* 初始化字体管理器（加载中文字体） */
1515	  font_manager_init();
1516	
1517	  /* 创建UI */
1518	  ui_create(&g_app);
1519	
1520	  /* 启动UI刷新定时器，每100ms刷新一次 */
1521	  if (ui_refresh_timer == NULL)
1522	    {
1523	      ui_refresh_timer = lv_timer_create(ui_refresh_timer_cb, 100, NULL);
1524	    }
1525	}
1526	
1527	void xiaozhi_voice_delete(void)
1528	{
