0	/****************************************************************************
1	 * apps/examples/xiaozhi_voice/xiaozhi_audio.c
2	 *
3	 * Audio capture (mic -> Opus 16kHz) and playback (Opus 24kHz -> speaker)
4	 * using direct Opus API for encoding and Vela media framework for decoding.
5	 * The SMF framework's Opus encoder adds non-standard headers that break
6	 * compatibility with the xiaozhi server, so we use the Opus API directly
7	 * for encoding. For playback, the SMF decoder works correctly.
8	 *
9	 * SPDX-License-Identifier: Apache-2.0
10	 ****************************************************************************/
11	
12	#include <nuttx/config.h>
13	
14	#include <stdio.h>
15	#include <string.h>
16	#include <errno.h>
17	#include <pthread.h>
18	
19	#include <opus.h>
20	
21	#include <media_recorder.h>
22	#include <media_player.h>
23	#include <media_defs.h>
24	
25	#include "xiaozhi_audio.h"
26	
27	/****************************************************************************
28	 * Pre-processor Definitions
29	 ****************************************************************************/
30	
31	/* Uplink: 16kHz mono Opus encoding parameters (direct API). */
32	#define XZ_OPUS_SAMPLE_RATE  16000
33	#define XZ_OPUS_CHANNELS     1
34	#define XZ_OPUS_BITRATE      32000
35	#define XZ_OPUS_FRAME_MS     60
36	#define XZ_OPUS_APPLICATION  OPUS_APPLICATION_VOIP
37	#define XZ_OPUS_FRAME_SIZE   (XZ_OPUS_SAMPLE_RATE * XZ_OPUS_FRAME_MS / 1000)  /* 960 samples */
38	
39	/* PCM capture options: raw 16-bit mono 16kHz from mic via SMF. */
40	#define XZ_PCM_RECORDER_OPTIONS \
41	  "fmt=[rate=#16000,ch=#1,bits=#16,width=#2],enc=[keys=pcm,imin=#1920]"
42	
43	/* Downlink: 24kHz mono Opus (xiaozhi server TTS sample rate, SMF native format). */
44	#define XZ_PLAYER_OPTIONS \
45	  "oMediaScript=[codec=opus,rate=#24000,ch=#1,bits=#16]"
46	
47	/* Max single Opus frame we expect / send. */
48	#define XZ_OPUS_FRAME_MAX 512
49	
50	/* PCM read buffer size: one 60ms frame at 16kHz mono 16-bit = 1920 bytes. */
51	#define XZ_PCM_BUF_SIZE (XZ_OPUS_FRAME_SIZE * XZ_OPUS_CHANNELS * sizeof(opus_int16))
52	
53	/****************************************************************************
54	 * Private Data
55	 ****************************************************************************/
56	
57	struct xiaozhi_audio_s
58	{
59	  /* Recording path (mic -> PCM -> Opus encode -> send). */
60	  void             *recorder;       /* SMF recorder handle (void*). */
61	  OpusEncoder      *opus_encoder;   /* Direct Opus encoder. */
62	  opus_int16        pcm_buf[XZ_OPUS_FRAME_SIZE * XZ_OPUS_CHANNELS];
63	  uint8_t           opus_buf[XZ_OPUS_FRAME_MAX];
64	  pthread_mutex_t   enc_mutex;
65	
66	  /* Playback path (recv Opus -> SMF decode -> speaker). */
67	  void             *player;         /* SMF player handle (void*). */
68	};
69	
70	static struct xiaozhi_audio_s g_audio;
71	
72	/****************************************************************************
73	 * Public Functions
74	 ****************************************************************************/
75	
76	struct xiaozhi_audio_s *xiaozhi_audio_init(void)
77	{
78	  struct xiaozhi_audio_s *a = &g_audio;
79	  int err;
80	
81	  memset(a, 0, sizeof(*a));
82	  pthread_mutex_init(&a->enc_mutex, NULL);
83	
84	  /* Create Opus encoder: 16kHz mono, VOIP application, 60ms frames. */
85	  a->opus_encoder = opus_encoder_create(XZ_OPUS_SAMPLE_RATE,
86	                                        XZ_OPUS_CHANNELS,
87	                                        XZ_OPUS_APPLICATION,
88	                                        &err);
89	  if (a->opus_encoder == NULL)
90	    {
91	      printf("[xiaozhi] opus_encoder_create failed: %s\n", opus_strerror(err));
92	      return NULL;
93	    }
94	
95	  /* Configure encoder for xiaozhi compatibility. */
96	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_BITRATE(XZ_OPUS_BITRATE));
97	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_COMPLEXITY(5));
98	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_SIGNAL(OPUS_SIGNAL_VOICE));
99	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_LSB_DEPTH(16));
100	  /* Force 60ms frame size. */
101	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_PACKET_LOSS_PERC(0));
102	
103	  printf("[xiaozhi] opus encoder created: %dHz %dch %dbps %dms frame\n",
104	         XZ_OPUS_SAMPLE_RATE, XZ_OPUS_CHANNELS, XZ_OPUS_BITRATE,
105	         XZ_OPUS_FRAME_MS);
106	
107	  return a;
108	}
109	
110	int xiaozhi_audio_start_capture(struct xiaozhi_audio_s *a)
111	{
112	  int ret;
113	
114	  if (a == NULL)
115	    {
116	      return -EINVAL;
117	    }
118	
119	  /* Tear down any previous recorder. */
120	  if (a->recorder != NULL)
121	    {
122	      media_recorder_stop(a->recorder);
123	      media_recorder_close(a->recorder);
124	      a->recorder = NULL;
125	    }
126	
127	  a->recorder = media_recorder_open(MEDIA_SOURCE_MIC);
128	  if (a->recorder == NULL)
129	    {
130	      printf("[xiaozhi] media_recorder_open failed\n");
131	      return -EIO;
132	    }
133	
134	  /* Buffer mode: capture raw PCM. We encode to Opus ourselves. */
135	  ret = media_recorder_prepare(a->recorder, NULL, XZ_PCM_RECORDER_OPTIONS);
136	  if (ret < 0)
137	    {
138	      printf("[xiaozhi] recorder prepare failed: %d\n", ret);
139	      media_recorder_close(a->recorder);
140	      a->recorder = NULL;
141	      return ret;
142	    }
143	
144	  ret = media_recorder_start(a->recorder);
145	  if (ret < 0)
146	    {
147	      printf("[xiaozhi] recorder start failed: %d\n", ret);
148	      media_recorder_close(a->recorder);
149	      a->recorder = NULL;
150	      return ret;
151	    }
152	
153	  printf("[xiaozhi] capture started (16k PCM -> opus encode)\n");
154	  return 0;
155	}
156	
157	ssize_t xiaozhi_audio_read_opus(struct xiaozhi_audio_s *a,
158	                                uint8_t *buf, size_t maxlen)
159	{
160	  ssize_t total = 0;
161	  ssize_t n;
162	  int encoded_bytes;
163	  int frame_samples;
164	
165	  if (a == NULL || a->recorder == NULL || buf == NULL)
166	    {
167	      return -EINVAL;
168	    }
169	
170	  /* Read exactly one 60ms PCM frame from the SMF recorder.
171	   * At 16kHz mono 16-bit, one 60ms frame = 960 samples = 1920 bytes.
172	   * media_recorder_read_data may return partial reads, so loop until
173	   * we have the full frame.
174	   */
175	  while (total < XZ_PCM_BUF_SIZE)
176	    {
177	      n = media_recorder_read_data(a->recorder,
178	                                   (uint8_t *)a->pcm_buf + total,
179	                                   XZ_PCM_BUF_SIZE - total);
180	      if (n <= 0)
181	        {
182	          printf("[xiaozhi] pcm read returned: %zd (got %zd/%d)\n",
183	                 n, total, XZ_PCM_BUF_SIZE);
184	          return n > 0 ? -EIO : n;
185	        }
186	
187	      total += n;
188	    }
189	
190	  /* Encode PCM to Opus. opus_encode takes sample count, not byte count.
191	   * frame_samples = total_bytes / (channels * bytes_per_sample)
192	   *               = 1920 / (1 * 2) = 960 samples for 60ms at 16kHz.
193	   */
194	  frame_samples = total / (XZ_OPUS_CHANNELS * sizeof(opus_int16));
195	  encoded_bytes = opus_encode(a->opus_encoder,
196	                              a->pcm_buf,
197	                              frame_samples,
198	                              a->opus_buf,
199	                              XZ_OPUS_FRAME_MAX);

200	                              XZ_OPUS_FRAME_MAX);
201	  if (encoded_bytes < 0)
202	    {
203	      printf("[xiaozhi] opus_encode error: %s (samples=%d)\n",
204	             opus_strerror(encoded_bytes), frame_samples);
205	      return -EIO;
206	    }
207	
208	  /* Copy encoded frame to caller's buffer. */
209	  if ((size_t)encoded_bytes > maxlen)
210	    {
211	      printf("[xiaozhi] opus frame too large: %d > %zu\n", encoded_bytes, maxlen);
212	      return -ENOMEM;
213	    }
214	
215	  memcpy(buf, a->opus_buf, encoded_bytes);
216	
217	  return (ssize_t)encoded_bytes;
218	}
219	
220	int xiaozhi_audio_stop_capture(struct xiaozhi_audio_s *a)
221	{
222	  if (a == NULL || a->recorder == NULL)
223	    {
224	      return -EINVAL;
225	    }
226	
227	  media_recorder_stop(a->recorder);
228	  media_recorder_close(a->recorder);
229	  a->recorder = NULL;
230	  printf("[xiaozhi] capture stopped\n");
231	  return 0;
232	}
233	
234	int xiaozhi_audio_start_playback(struct xiaozhi_audio_s *a)
235	{
236	  int ret;
237	
238	  if (a == NULL)
239	    {
240	      return -EINVAL;
241	    }
242	
243	  if (a->player != NULL)
244	    {
245	      media_player_stop(a->player);
246	      media_player_close(a->player, 0);
247	      a->player = NULL;
248	    }
249	
250	  a->player = media_player_open(MEDIA_STREAM_MUSIC);
251	  if (a->player == NULL)
252	    {
253	      printf("[xiaozhi] media_player_open failed\n");
254	      return -EIO;
255	    }
256	
257	  /* Buffer mode: url = NULL. The framework decodes Opus; we feed encoded
258	   * frames via media_player_write_data().
259	   */
260	  ret = media_player_prepare(a->player, NULL, XZ_PLAYER_OPTIONS);
261	  if (ret < 0)
262	    {
263	      printf("[xiaozhi] player prepare failed: %d\n", ret);
264	      media_player_close(a->player, 0);
265	      a->player = NULL;
266	      return ret;
267	    }
268	
269	  ret = media_player_start(a->player);
270	  if (ret < 0)
271	    {
272	      printf("[xiaozhi] player start failed: %d\n", ret);
273	      media_player_close(a->player, 0);
274	      a->player = NULL;
275	      return ret;
276	    }
277	
278	  printf("[xiaozhi] playback started (24k opus)\n");
279	  return 0;
280	}
281	
282	int xiaozhi_audio_write_opus(struct xiaozhi_audio_s *a,
283	                             const uint8_t *data, size_t len)
284	{
285	  ssize_t ret;
286	
287	  if (a == NULL || a->player == NULL || data == NULL)
288	    {
289	      return -EINVAL;
290	    }
291	
292	  ret = media_player_write_data(a->player, data, len);
293	  if (ret < 0)
294	    {
295	      printf("[xiaozhi] player write_data failed: %zd\n", ret);
296	      return ret;
297	    }
298	
299	  return 0;
300	}
301	
302	int xiaozhi_audio_stop_playback(struct xiaozhi_audio_s *a)
303	{
304	  if (a == NULL || a->player == NULL)
305	    {
306	      return -EINVAL;
307	    }
308	
309	  media_player_stop(a->player);
310	  media_player_close(a->player, 0);
311	  a->player = NULL;
312	  printf("[xiaozhi] playback stopped\n");
313	  return 0;
314	}
315	
316	void xiaozhi_audio_deinit(struct xiaozhi_audio_s *a)
317	{
318	  if (a == NULL)
319	    {
320	      return;
321	    }
322	
323	  if (a->recorder != NULL)
324	    {
325	      media_recorder_stop(a->recorder);
326	      media_recorder_close(a->recorder);
327	      a->recorder = NULL;
328	    }
329	
330	  if (a->player != NULL)
331	    {
332	      media_player_stop(a->player);
333	      media_player_close(a->player, 0);
334	      a->player = NULL;
335	    }
336	
337	  if (a->opus_encoder != NULL)
338	    {
339	      opus_encoder_destroy(a->opus_encoder);
340	      a->opus_encoder = NULL;
341	    }
342	
343	  pthread_mutex_destroy(&a->enc_mutex);
344	}
