1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_ws.c
3	 *
4	 * A lightweight WebSocket-over-TLS (wss) client.
5	 *   - TLS layer: mbedtls (pattern borrowed from packages/demos/mimo)
6	 *   - WebSocket framing: RFC 6455
7	 *
8	 * Supports the subset needed by the xiaozhi protocol:
9	 *   - client->server text(0x1) and binary(0x2) frames, masked
10	 *   - server->client text/binary/close frames, unmasked
11	 *   - payload lengths up to 65535 (16-bit length); 64-bit length not needed
12	 *     here (Opus frames and JSON messages are short)
13	 *
14	 * SPDX-License-Identifier: Apache-2.0
15	 ****************************************************************************/
16	
17	#include <nuttx/config.h>
18	
19	#include <stdio.h>
20	#include <string.h>
21	#include <stdlib.h>
22	#include <errno.h>
23	#include <unistd.h>
24	#include <netdb.h>
25	#include <netinet/in.h>
26	#include <arpa/inet.h>
27	#include <sys/socket.h>
28	#include <sys/time.h>
29	
30	#include "xiaozhi_ws.h"
31	
32	/****************************************************************************
33	 * Pre-processor Definitions
34	 ****************************************************************************/
35	
36	#define WS_RXBUF_SIZE  4096
37	
38	/* WebSocket opcodes */
39	#define WS_OPCODE_CONTINUATION 0x0
40	#define WS_OPCODE_TEXT         0x1
41	#define WS_OPCODE_BINARY       0x2
42	#define WS_OPCODE_CLOSE        0x8
43	#define WS_OPCODE_PING         0x9
44	#define WS_OPCODE_PONG         0xa
45	
46	#define WS_FIN_BIT   0x80
47	#define WS_MASK_BIT  0x80
48	
49	/****************************************************************************
50	 * Private Functions - TLS
51	 ****************************************************************************/
52	
53	/* BIO send: write to the plain TCP fd. */
54	static int ws_bio_send(void *ctx, const unsigned char *buf, size_t len)
55	{
56	  int fd = *(int *)ctx;
57	  ssize_t ret = send(fd, buf, len, 0);
58	  if (ret < 0)
59	    {
60	      return -EIO;
61	    }
62	
63	  return (int)ret;
64	}
65	
66	/* BIO recv: read from the plain TCP fd. */
67	static int ws_bio_recv(void *ctx, unsigned char *buf, size_t len)
68	{
69	  int fd = *(int *)ctx;
70	  ssize_t ret = recv(fd, buf, len, 0);
71	  if (ret < 0)
72	    {
73	      return -EIO;
74	    }
75	
76	  if (ret == 0)
77	    {
78	      return MBEDTLS_ERR_SSL_WANT_READ;
79	    }
80	
81	  return (int)ret;
82	}
83	
84	static int ws_tls_init(struct xiaozhi_ws_s *ws)
85	{
86	  int ret;
87	
88	  mbedtls_ssl_init(&ws->ssl);
89	  mbedtls_ssl_config_init(&ws->conf);
90	  mbedtls_entropy_init(&ws->entropy);
91	  mbedtls_ctr_drbg_init(&ws->ctr_drbg);
92	
93	  ret = mbedtls_ctr_drbg_seed(&ws->ctr_drbg, mbedtls_entropy_func,
94	                              &ws->entropy,
95	                              (const unsigned char *)"xiaozhi", 7);
96	  if (ret != 0)
97	    {
98	      printf("[xiaozhi] drbg seed failed: -0x%x\n", -ret);
99	      return -EIO;
100	    }
101	
102	  ret = mbedtls_ssl_config_defaults(&ws->conf, MBEDTLS_SSL_IS_CLIENT,
103	                                    MBEDTLS_SSL_TRANSPORT_STREAM,
104	                                    MBEDTLS_SSL_PRESET_DEFAULT);
105	  if (ret != 0)
106	    {
107	      printf("[xiaozhi] ssl config defaults failed: -0x%x\n", -ret);
108	      return -EIO;
109	    }
110	
111	  /* Skip server cert verification for embedded use.
112	   * For production, configure CA certs via mbedtls_ssl_conf_ca_chain().
113	   */
114	  mbedtls_ssl_conf_authmode(&ws->conf, MBEDTLS_SSL_VERIFY_NONE);
115	  mbedtls_ssl_conf_rng(&ws->conf, mbedtls_ctr_drbg_random, &ws->ctr_drbg);
116	
117	  ret = mbedtls_ssl_setup(&ws->ssl, &ws->conf);
118	  if (ret != 0)
119	    {
120	      printf("[xiaozhi] ssl setup failed: -0x%x\n", -ret);
121	      return -EIO;
122	    }
123	
124	  return 0;
125	}
126	
127	/* Connect TCP, do TLS handshake over it. */
128	static int ws_tls_connect(struct xiaozhi_ws_s *ws, const char *host,
129	                         const char *port)
130	{
131	  struct hostent *he;
132	  struct sockaddr_in server;
133	  int portnum = atoi(port);
134	  int ret;
135	
136	  printf("[xiaozhi] TLS connecting to %s:%s\n", host, port);
137	
138	  he = gethostbyname(host);
139	  if (he == NULL)
140	    {
141	      printf("[xiaozhi] DNS resolve failed for %s\n", host);
142	      return -EIO;
143	    }
144	
145	  ws->fd = socket(AF_INET, SOCK_STREAM, 0);
146	  if (ws->fd < 0)
147	    {
148	      printf("[xiaozhi] socket() failed: %d\n", errno);
149	      return -EIO;
150	    }
151	
152	  memset(&server, 0, sizeof(server));
153	  server.sin_family = AF_INET;
154	  server.sin_port   = htons(portnum);
155	  memcpy(&server.sin_addr, he->h_addr_list[0], he->h_length);
156	
157	  printf("[xiaozhi] TCP connect to %s:%d\n",
158	         inet_ntoa(server.sin_addr), portnum);
159	
160	  if (connect(ws->fd, (struct sockaddr *)&server, sizeof(server)) < 0)
161	    {
162	      printf("[xiaozhi] TCP connect failed: %d\n", errno);
163	      close(ws->fd);
164	      ws->fd = -1;
165	      return -EIO;
166	    }
167	
168	  /* Set socket send/recv timeouts to prevent blocking forever */
169	
170	  struct timeval tv;
171	  tv.tv_sec = 10;
172	  tv.tv_usec = 0;
173	  setsockopt(ws->fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
174	  setsockopt(ws->fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
175	
176	  printf("[xiaozhi] TCP connected, starting TLS handshake\n");
177	
178	  ret = mbedtls_ssl_set_hostname(&ws->ssl, host);
179	  if (ret != 0)
180	    {
181	      printf("[xiaozhi] set hostname failed: -0x%x\n", -ret);
182	      goto err;
183	    }
184	
185	  mbedtls_ssl_set_bio(&ws->ssl, &ws->fd, ws_bio_send, ws_bio_recv, NULL);
186	
187	  int hs_retries = 0;
188	  while ((ret = mbedtls_ssl_handshake(&ws->ssl)) != 0)
189	    {
190	      if (ret != MBEDTLS_ERR_SSL_WANT_READ &&
191	          ret != MBEDTLS_ERR_SSL_WANT_WRITE)
192	        {
193	          printf("[xiaozhi] TLS handshake failed: -0x%x\n", -ret);
194	          goto err;
195	        }
196	      if (++hs_retries >= 20)
197	        {
198	          printf("[xiaozhi] TLS handshake timeout\n");
199	          goto err;
200	        }
201	      usleep(500000);
202	    }
203	
204	  printf("[xiaozhi] TLS handshake complete\n");
205	  return 0;
206	
207	err:
208	  close(ws->fd);
209	  ws->fd = -1;
210	  return -EIO;
211	}
212	
213	/****************************************************************************
214	 * Private Functions - TLS read/write wrappers
215	 ****************************************************************************/
216	
217	/* Send all bytes over TLS. Returns 0 on success, -errno on failure. */
218	static int ws_tls_write_all(struct xiaozhi_ws_s *ws,
219	                            const uint8_t *buf, size_t len)
220	{
221	  size_t written = 0;
222	  while (written < len)
223	    {
224	      int ret = mbedtls_ssl_write(&ws->ssl, buf + written, len - written);
225	      if (ret == MBEDTLS_ERR_SSL_WANT_WRITE ||
226	          ret == MBEDTLS_ERR_SSL_WANT_READ)
227	        {
228	          continue;
229	        }
230	
231	      if (ret <= 0)
232	        {
233	          printf("[xiaozhi] tls write error: -0x%x\n", -ret);
234	          return -EIO;
235	        }
236	
237	      written += ret;
238	    }
239	
240	  return 0;
241	}
242	
243	/* Read exactly n bytes over TLS into buf. Returns 0 on success, -errno. */
244	static int ws_tls_read_all(struct xiaozhi_ws_s *ws, uint8_t *buf, size_t n)
245	{
246	  size_t got = 0;
247	  while (got < n)
248	    {
249	      int ret = mbedtls_ssl_read(&ws->ssl, buf + got, n - got);
250	      if (ret == MBEDTLS_ERR_SSL_WANT_READ ||
251	          ret == MBEDTLS_ERR_SSL_WANT_WRITE)
252	        {
253	          continue;
254	        }
255	
256	      if (ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY || ret == 0)
257	        {
258	          printf("[xiaozhi] tls peer closed during read\n");
259	          return -ECONNRESET;
260	        }
261	
262	      if (ret < 0)
263	        {
264	          printf("[xiaozhi] tls read error: -0x%x\n", -ret);
265	          return -EIO;
266	        }
267	
268	      got += ret;
269	    }
270	
271	  return 0;
272	}
