274	/****************************************************************************
275	 * Private Functions - WebSocket framing
276	 ****************************************************************************/
277	
278	/* Generate a random 4-byte masking key. mbedtls_ctr_drbg_random is used as
279	 * a random source (no Date.now/random needed).
280	 */
281	static void ws_make_mask(uint8_t mask[4], struct xiaozhi_ws_s *ws)
282	{
283	  mbedtls_ctr_drbg_random(&ws->ctr_drbg, mask, 4);
284	}
285	
286	/* Send one client->server frame (masked). */
287	static int ws_send_frame(struct xiaozhi_ws_s *ws, uint8_t opcode,
288	                         const uint8_t *data, size_t len)
289	{
290	  uint8_t hdr[14];
291	  size_t hdrlen;
292	  uint8_t mask[4];
293	  int ret;
294	
295	  hdr[0] = WS_FIN_BIT | opcode;
296	
297	  if (len <= 125)
298	    {
299	      hdr[1] = WS_MASK_BIT | (uint8_t)len;
300	      hdrlen = 2;
301	    }
302	  else if (len <= 65535)
303	    {
304	      hdr[1] = WS_MASK_BIT | 126;
305	      hdr[2] = (len >> 8) & 0xff;
306	      hdr[3] = len & 0xff;
307	      hdrlen = 4;
308	    }
309	  else
310	    {
311	      /* 64-bit length path. Opus/JSON frames are never this large, but
312	       * implement for completeness.
313	       */
314	      hdr[1] = WS_MASK_BIT | 127;
315	      uint64_t l = len;
316	      hdr[2] = 0; hdr[3] = 0; hdr[4] = 0; hdr[5] = 0;
317	      hdr[6] = (l >> 24) & 0xff;
318	      hdr[7] = (l >> 16) & 0xff;
319	      hdr[8] = (l >> 8) & 0xff;
320	      hdr[9] = l & 0xff;
321	      hdrlen = 10;
322	    }
323	
324	  ret = ws_tls_write_all(ws, hdr, hdrlen);
325	  if (ret != 0)
326	    {
327	      return ret;
328	    }
329	
330	  /* Masking key + masked payload. */
331	  ws_make_mask(mask, ws);
332	  ret = ws_tls_write_all(ws, mask, 4);
333	  if (ret != 0)
334	    {
335	      return ret;
336	    }
337	
338	  if (len > 0)
339	    {
340	      /* XOR the payload in a stack buffer to keep rxbuf/data const.
341	       * For large frames a streaming XOR would be better; xiaozhi payloads
342	       * are small (Opus <= ~400B, JSON <= ~2KB).
343	       */
344	      uint8_t masked[1];
345	      for (size_t i = 0; i < len; i++)
346	        {
347	          masked[0] = data[i] ^ mask[i & 3];
348	          ret = ws_tls_write_all(ws, masked, 1);
349	          if (ret != 0)
350	            {
351	              return ret;
352	            }
353	        }
354	    }
355	
356	  return 0;
357	}
