360	 * Public Functions
361	 ****************************************************************************/
362	
363	int xiaozhi_ws_connect(struct xiaozhi_ws_s *ws, const char *ws_url,
364	                       const char *token, const char *device_id,
365	                       const char *client_id)
366	{
367	  char host[128];
368	  char path[256];
369	  char pathwithtok[320];   /* path + ?token=<token> for the GET line */
370	  char portstr[8];
371	  const char *p;
372	  const char *hoststart;
373	  const char *hostend;
374	  const char *pathstart;
375	  int port = 443;
376	  int ret;
377	  uint8_t wskey[16];
378	  char req[768];
379	
380	  memset(ws, 0, sizeof(*ws));
381	  ws->fd = -1;
382	
383	  /* Parse "wss://host[:port]/path..." */
384	  if (strncmp(ws_url, "wss://", 6) != 0)
385	    {
386	      printf("[xiaozhi] ws url must be wss://: %s\n", ws_url);
387	      return -EINVAL;
388	    }
389	
390	  hoststart = ws_url + 6;
391	  pathstart = strchr(hoststart, '/');
392	  hostend   = pathstart ? pathstart : hoststart + strlen(hoststart);
393	
394	  /* Detect port in host portion */
395	  p = memchr(hoststart, ':', hostend - hoststart);
396	  if (p != NULL)
397	    {
398	      size_t hlen = p - hoststart;
399	      memcpy(host, hoststart, hlen);
400	      host[hlen] = '\0';
401	      port = atoi(p + 1);
402	    }
403	  else
404	    {
405	      size_t hlen = hostend - hoststart;
406	      memcpy(host, hoststart, hlen);
407	      host[hlen] = '\0';
408	    }
409	
410	  snprintf(portstr, sizeof(portstr), "%d", port);
411	
412	  if (pathstart)
413	    {
414	      snprintf(path, sizeof(path), "%s", pathstart);
415	    }
416	  else
417	    {
418	      path[0] = '/'; path[1] = '\0';
419	    }
420	
421	  /* The xiaozhi server expects the token both as a query string on the GET
422	   * line (?token=<token>) and as an Authorization: Bearer ***REDACTED*** The
423	   * working Python probe builds "{ws_url}?token={ws_token}". Append it
424	   * here when the server's URL doesn't already carry one.
425	   */
426	  if (token != NULL && token[0] != '\0' && strchr(path, '?') == NULL)
427	    {
428	      snprintf(pathwithtok, sizeof(pathwithtok), "%s?token=%s", path, token);
429	    }
430	  else
431	    {
432	      snprintf(pathwithtok, sizeof(pathwithtok), "%s", path);
433	    }
434	
435	  printf("[xiaozhi] ws host=%s port=%d path=%s token=%s\n",
436	         host, port, pathwithtok, token);
437	
438	  /* Allocate rx buffer. */
439	  ws->rxbuf_cap = WS_RXBUF_SIZE;
440	  ws->rxbuf = malloc(ws->rxbuf_cap);
441	  if (ws->rxbuf == NULL)
442	    {
443	      return -ENOMEM;
444	    }
445	
446	  /* TLS init + connect. */
447	  ret = ws_tls_init(ws);
448	  if (ret != 0)
449	    {
450	      return ret;
451	    }
452	
453	  ret = ws_tls_connect(ws, host, portstr);
454	  if (ret != 0)
455	    {
456	      return ret;
457	    }
458	
459	  /* WebSocket HTTP Upgrade handshake. */
460	  mbedtls_ctr_drbg_random(&ws->ctr_drbg, wskey, 16);
461	
462	  /* Build Sec-WebSocket-Key (base64 of 16 random bytes). We use a tiny
463	   * base64 encoder below.
464	   */
465	  char wskey_b64[32];
466	  {
467	    const char b64[] =
468	      "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
469	    int o = 0;
470	    int i;
471	    for (i = 0; i < 16; i += 3)
472	      {
473	        uint32_t v = (wskey[i] << 16);
474	        if (i + 1 < 16) v |= (wskey[i + 1] << 8);
475	        if (i + 2 < 16) v |= wskey[i + 2];
476	        wskey_b64[o++] = b64[(v >> 18) & 0x3f];
477	        wskey_b64[o++] = b64[(v >> 12) & 0x3f];
478	        wskey_b64[o++] = (i + 1 < 16) ? b64[(v >> 6) & 0x3f] : '=';
479	        wskey_b64[o++] = (i + 2 < 16) ? b64[v & 0x3f] : '=';
480	      }
481	
482	    wskey_b64[o] = '\0';
483	  }
484	
485	  snprintf(req, sizeof(req),
486	    "GET %s HTTP/1.1\r\n"
487	    "Host: %s\r\n"
488	    "Upgrade: websocket\r\n"
489	    "Connection: Upgrade\r\n"
490	    "Sec-WebSocket-Key: %s\r\n"
491	    "Sec-WebSocket-Version: 13\r\n"
492	    "Authorization: Bearer %s\r\n"
493	    "Device-Id: %s\r\n"
494	    "Client-Id: %s\r\n"
495	    "Protocol-Version: 1\r\n"
496	    "\r\n",
497	    pathwithtok, host, wskey_b64, token, device_id, client_id);
498	
499	  printf("[xiaozhi] sending ws upgrade request (%zu bytes)\n", strlen(req));
500	
501	  ret = ws_tls_write_all(ws, (const uint8_t *)req, strlen(req));
502	  if (ret != 0)
503	    {
504	      return ret;
505	    }
506	
507	  /* Read the HTTP response line + headers until blank line. */
508	  {
509	    char line[256];
510	    int got101 = 0;
511	
512	    /* Read line-by-line until \r\n\r\n */
513	    for (;;)
514	      {
515	        size_t li = 0;
516	        char prev = 0;
517	
518	        while (li < sizeof(line) - 1)
519	          {
520	            uint8_t b;
521	            ret = ws_tls_read_all(ws, &b, 1);
522	            if (ret != 0)
523	              {
524	                return ret;
525	              }
526	
527	            line[li] = (char)b;
528	            if (line[li] == '\n' && prev == '\r')
529	              {
530	                break;
531	              }
532	
533	            prev = line[li];
534	            li++;
535	          }
536	
537	        line[li] = '\0';
538	
539	        /* Strip trailing \r\n */
540	        while (li > 0 && (line[li - 1] == '\r' || line[li - 1] == '\n'))
541	          {
542	            line[--li] = '\0';
543	          }
544	
545	        if (li == 0)
546	          {
547	            break;  /* blank line: end of headers */
548	          }
549	
550	        if (strstr(line, "101") != NULL && !got101)
551	          {
552	            got101 = 1;
553	          }
554	
555	        printf("[xiaozhi] <<< %s\n", line);
556	      }
557	
558	    if (!got101)
559	      {
560	        printf("[xiaozhi] ws upgrade failed (no 101)\n");
561	        return -EIO;
562	      }
563	  }
564	
565	  ws->connected = true;
566	  printf("[xiaozhi] WebSocket connected & upgraded\n");
567	  return 0;
568	}
