570	int xiaozhi_ws_send_text(struct xiaozhi_ws_s *ws, const char *data,
571	                         size_t len)
572	{
573	  if (!ws->connected)
574	    {
575	      return -ENOTCONN;
576	    }
577	
578	  return ws_send_frame(ws, WS_OPCODE_TEXT, (const uint8_t *)data, len);
579	}
