581	int xiaozhi_ws_send_binary(struct xiaozhi_ws_s *ws,
582	                           const uint8_t *data, size_t len)
583	{
584	  if (!ws->connected)
585	    {
586	      return -ENOTCONN;
587	    }
588	
589	  return ws_send_frame(ws, WS_OPCODE_BINARY, data, len);
590	}
591	
592	int xiaozhi_ws_recv(struct xiaozhi_ws_s *ws, const uint8_t **payload,
593	                    size_t *plen, bool *is_binary)
594	{
595	  uint8_t hdr[2];
596	  uint8_t mask[4];
597	  uint8_t opcode;
598	  bool masked;
599	  uint64_t plen64;
600	  int ret;
601	
602	  if (!ws->connected)
603	    {
604	      return -ENOTCONN;
605	    }
606	
607	  /* Read the first 2 bytes of the frame header. */
608	  ret = ws_tls_read_all(ws, hdr, 2);
609	  if (ret != 0)
610	    {
611	      return ret;
612	    }
613	
614	  opcode = hdr[0] & 0x0f;
615	  masked = (hdr[1] & WS_MASK_BIT) != 0;
616	  plen64 = hdr[1] & 0x7f;
617	
618	  if (plen64 == 126)
619	    {
620	      uint8_t ext[2];
621	      ret = ws_tls_read_all(ws, ext, 2);
622	      if (ret != 0)
623	        {
624	          return ret;
625	        }
626	
627	      plen64 = ((uint64_t)ext[0] << 8) | ext[1];
628	    }
629	  else if (plen64 == 127)
630	    {
631	      uint8_t ext[8];
632	      ret = ws_tls_read_all(ws, ext, 8);
633	      if (ret != 0)
634	        {
635	          return ret;
636	        }
637	
638	      plen64 = 0;
639	      for (int i = 0; i < 8; i++)
640	        {
641	          plen64 = (plen64 << 8) | ext[i];
642	        }
643	    }
644	
645	  if (masked)
646	    {
647	      ret = ws_tls_read_all(ws, mask, 4);
648	      if (ret != 0)
649	        {
650	          return ret;
651	        }
652	    }
653	
654	  if (plen64 > ws->rxbuf_cap)
655	    {
656	      printf("[xiaozhi] frame too large: %llu\n",
657	             (unsigned long long)plen64);
658	      return -EMSGSIZE;
659	    }
660	
661	  /* Read the payload. */
662	  if (plen64 > 0)
663	    {
664	      ret = ws_tls_read_all(ws, ws->rxbuf, plen64);
665	      if (ret != 0)
666	        {
667	          return ret;
668	        }
669	
670	      if (masked)
671	        {
672	          for (uint64_t i = 0; i < plen64; i++)
673	            {
674	              ws->rxbuf[i] ^= mask[i & 3];
675	            }
676	        }
677	    }
678	
679	  /* Handle control frames transparently. */
680	  if (opcode == WS_OPCODE_CLOSE)
681	    {
682	      printf("[xiaozhi] server sent close frame\n");
683	      ws->connected = false;
684	      return -ECONNRESET;
685	    }
686	
687	  if (opcode == WS_OPCODE_PING)
688	    {
689	      /* Echo as pong. */
690	      ws_send_frame(ws, WS_OPCODE_PONG, ws->rxbuf, plen64);
691	      return xiaozhi_ws_recv(ws, payload, plen, is_binary);
692	    }
693	
694	  if (opcode == WS_OPCODE_PONG)
695	    {
696	      /* Ignore. */
697	      return xiaozhi_ws_recv(ws, payload, plen, is_binary);
698	    }
699	
700	  /* Text or binary. */
701	  *payload    = ws->rxbuf;
702	  *plen       = plen64;
703	  *is_binary  = (opcode == WS_OPCODE_BINARY);
704	  return 0;
705	}
706	
707	void xiaozhi_ws_close(struct xiaozhi_ws_s *ws)
708	{
709	  if (ws->connected)
710	    {
711	      uint8_t close_frame[] = { 0x88, 0x00 };
712	      ws_tls_write_all(ws, close_frame, 2);
713	    }
714	
715	  mbedtls_ssl_close_notify(&ws->ssl);
716	  mbedtls_ssl_free(&ws->ssl);
717	  mbedtls_ssl_config_free(&ws->conf);
718	  mbedtls_ctr_drbg_free(&ws->ctr_drbg);
719	  mbedtls_entropy_free(&ws->entropy);
720	
721	  if (ws->fd >= 0)
722	    {
723	      close(ws->fd);
724	      ws->fd = -1;
725	    }
726	
727	  if (ws->rxbuf)
728	    {
729	      free(ws->rxbuf);
730	      ws->rxbuf = NULL;
731	    }
732	
733	  ws->connected = false;
734	}
